<?php
class med_cisz_contract_rejectionBy_builder { private med_cisz_context $context; use med_cisz_utilsTrait; use med_cisz_contract_constTrait; use med_cisz_contract_rejectionBy_constTrait; public function __construct(med_cisz_context $context) { $this->context = $context; } public function build(object $data): object { $id = generateUUID(); $patient = $this->context->getPatient(); $extension = [$this->getReasonExtension($data)]; $authoredOnDate = self::getDate($data->jsonData->authoredOn) ?? ''; return (object)[ 'fullUrl' => 'Contract/' . $id, 'resource' => (object)[ 'resourceType' => self::RESOURCE_TYPE, 'meta' => (object)[ 'profile' => [ self::PROFILE_URL ] ], 'extension' => $extension, 'status' => 'executed', 'issued' => self::getDateTime($data->leaveTime ?? date('c')), 'subject' => [ (object) [ 'reference' => $patient->link->reference ] ], 'title' => 'Отказ от направления на госпитализацию от ' . $authoredOnDate, 'author' => $this->getAuthor($data), 'topicReference' => (object) [ 'reference' => med_cisz_serviceRequest_main::RESOURCE_TYPE . '/' . ($data->jsonData->referralId ?? '') ] ] ]; } private function getAuthor(object $data): object { if ($data->rejectBy === 1) { return (object) [ 'reference' => $this->context->getPatient()->link->reference ]; } if ($data->rejectBy === 2) { return $this->context->getOrganization()->link; } throw new Error('Не указан инициатор отказа.'); } private function getReasonExtension(object $data): object { if ($data->rejectBy === 1) { return (object)[ 'url' => med_cisz_constant::$structureDefinitions['RejectionReason'], 'valueCodeableConcept' => self::getCodingStructure( med_cisz_constant::$valueSet['ServiceRequestRejectionReasonPatient'], $data->ciszCodeReason ) ]; } if ($data->rejectBy === 2) { return (object)[ 'url' => med_cisz_constant::$structureDefinitions['CancellationReason'], 'valueCodeableConcept' => self::getCodingStructure( med_cisz_constant::$valueSet['VSServiceRequestRejectionReasonProvider'], $data->ciszCodeReason ) ]; } } }